            new float[] { 172.7f,-40.5f, 174.3f,-41.3f, 173.3f,-43, 172.7f,-43.8f, 171.2f,-44.5f, 170.6f,-45.9f, 168.3f,-46.6f, 166.5f,-46, 168.2f,-44, 170.7f,-42.8f, 172.1f,-41 },
            // Antarctica
            new float[] { -180,-90, -180,-78, -160,-77, -150,-76, -120,-73.5f, -100,-73, -75,-72, -65,-66, -57,-63.3f, -60,-64.5f, -62,-70, -60,-74, -40,-78, -20,-73, 0,-70, 30,-69.5f, 60,-67, 90,-66, 120,-66.5f, 150,-68, 165,-71, 170,-75, 165,-78, 180,-78, 180,-90 },
        };

        /// <summary>Even-odd test across every polygon, so inland seas punch holes in the continents.</summary>
        public static bool IsLand(float lon, float lat)
        {
            bool inside = false;
            foreach (var poly in Polygons)
            {
                int n = poly.Length / 2;
                for (int i = 0, j = n - 1; i < n; j = i++)
                {
                    float xi = poly[i * 2], yi = poly[i * 2 + 1];
                    float xj = poly[j * 2], yj = poly[j * 2 + 1];
                    if ((yi > lat) != (yj > lat) && lon < (xj - xi) * (lat - yi) / (yj - yi) + xi)
                        inside = !inside;
                }
            }
            return inside;
        }
    }
}
